const item = $input.first().json.body || $input.first().json;

const proposalTitle = item.title || 'Amendment to Pet Leash and Pet Registration Bylaws';
const proposedBy = item.proposedBy || 'Managing Committee / Health Subcommittee';
const rawDescription = item.rawDescription || 'We want to make it compulsory that all pets in elevators must wear a muzzle or be carried, and owners who do not clean pet waste in garden will be fined 2000 rupees directly in maintenance bill.';
const category = item.category || 'BYLAW_AMENDMENT'; // BYLAW_AMENDMENT | CAPITAL_EXPENDITURE | PENALTY_POLICY | EASEMENT_RIGHT

const prompt = `You are the Senior Legal Counsel & Apartment Ownership Act Advisor for Mana Community Society.
Review and format the following proposed society resolution into formal, legally sound, and enforceable resolution text:

Proposal Dossier:
- Resolution Title: ${proposalTitle}
- Proponent: ${proposedBy}
- Category: ${category}
- Raw Proposal Intent:
"${rawDescription}"

Legal Review Directives:
1. Statutory Viability: Check if proposal conflicts with Indian law, Municipal Acts, or Animal Welfare Board of India (AWBI) directives (e.g. blanket bans on pets or arbitrary muzzling often violate AWBI guidelines).
2. Natural Justice & Proportionality: Ensure penalties include notice, hearing, and reasonable evidentiary standards (CCTV proof).
3. Statutory Majority Required: Specify if this requires Simple Majority (50%+1) or Special Resolution (two-thirds / 75%).
4. Formal Resolution Drafting: Formulate preamble ("WHEREAS..."), operative clause ("RESOLVED THAT..."), and enforcement authority.

Respond ONLY with a valid JSON object matching this schema:
{
  "legalViability": "LEGALLY_SOUND" | "MODIFICATIONS_REQUIRED" | "STATUTORY_VIOLATION_RISK",
  "complianceScore": number (0 to 100),
  "statutoryMajorityRequired": "SIMPLE_MAJORITY" | "TWO_THIRDS_MAJORITY" | "UNANIMOUS",
  "legalRiskAnalysis": [
    { "aspect": string, "riskLevel": "LOW" | "MEDIUM" | "HIGH", "advice": string }
  ],
  "formalResolutionText": {
    "whereasClauses": string[],
    "resolvedClauses": string[],
    "penaltyAndRemedyClause": string
  },
  "counselAdvisory": string
}`;

return [{ json: { prompt, proposalTitle, proposedBy } }];

const gemini = $input.first().json;
let parsed = {};
try {
  const raw = gemini.candidates[0].content.parts[0].text;
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    legalViability: "MODIFICATIONS_REQUIRED",
    complianceScore: 78,
    statutoryMajorityRequired: "TWO_THIRDS_MAJORITY",
    legalRiskAnalysis: [
      { aspect: "AWBI Pet Guidelines", riskLevel: "MEDIUM", advice: "Ensure penalties specify verifiable evidence (CCTV) and provide 3-day notice before debiting ledger." }
    ],
    formalResolutionText: {
      whereasClauses: ["WHEREAS the society seeks to maintain hygiene and safety across shared elevator lobbies."],
      resolvedClauses: ["RESOLVED THAT all pet owners shall ensure proper waste disposal and leashing in common corridors."],
      penaltyAndRemedyClause: "Violations substantiated with CCTV proof shall incur progressive fine after written notice."
    },
    counselAdvisory: "Recommended for general body tabling subject to natural justice notice provisions."
  };
}

const meta = $('Prepare AI Prompt').first().json;
return [{ json: { status: "success", title: meta.proposalTitle, formattedAt: new Date().toISOString(), legalReview: parsed } }];
